G=load()
def comps(g,bg=2):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; cur=[(r,c)]; seen.add((r,c)); cells=set()
                while cur:
                    rr,cc=cur.pop()
                    cells.add((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==col and (nr,nc) not in seen:
                            seen.add((nr,nc)); cur.append((nr,nc))
                out.append((col,frozenset(cells)))
    return out
def normsh(cells):
    rs=min(r for r,_ in cells); cc=min(c for _,c in cells)
    return tuple(sorted((r-rs,c-cc) for r,c in cells))
def solve(g,bg=2):
    cs=comps(g)
    # anchor: unique-color multi-cell component (color appears once, len>1, size>= max? use largest multi)
    cntc=Counter(c[0] for c in cs)
    anchors=[c for c in cs if cntc[c[0]]==1 and len(c[1])>1]
    if not anchors: return g
    anchors.sort(key=lambda c:-len(c[1])); anc=anchors[0]
    sh=normsh(anc[1]); tgt=anc[0]
    # duplicate groups: shapes shared by >=2 comps
    bysh=defaultdict(list)
    for c in cs: bysh[normsh(c[1])].append(c)
    groups={k:v for k,v in bysh.items() if len(v)>=2 and v}
    # changed member: farthest from anchor
    def dist(p,q): return abs(min(r for r,_ in p[1])-min(r for r,_ in q[1]))+abs(min(c for _,c in p[1])-min(c for _,c in q[1]))
    chgc=None
    for v in groups.values():
        best=None
        for c in v:
            d_ = dist(c,anc)
            if best is None or d_>best:
                best=d_; chgc=c
        # also prefer larger? tie-break min size first then topmost
        candidates=[(d_,len(c),min(r for r,_ in c[1]),min(c for _,cc in c[1]),c) for c in v]
        candidates.sort()
        chgc=candidates[0][4]
    newgrid=[row[:] for row in g]
    for r,cc in chgc[1]: newgrid[r][cc]=tgt
    return newgrid
